import React from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { Project } from '../types';
import { ArrowLeft, ExternalLink } from 'lucide-react';

interface ProjectDetailProps {
  projects: Project[];
}

const ProjectDetail: React.FC<ProjectDetailProps> = ({ projects }) => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const project = projects.find(p => p.id === id);

  React.useEffect(() => {
    window.scrollTo(0, 0);
  }, [id]);

  if (!project) {
    return (
      <div className="h-screen flex items-center justify-center">
        <p>프로젝트를 찾을 수 없습니다.</p>
        <button onClick={() => navigate('/')} className="ml-4 underline">홈으로</button>
      </div>
    );
  }

  return (
    <div className="pb-32 animate-fadeInUp">
      {/* Video Hero */}
      <div className="w-full aspect-video bg-black relative group">
        <iframe
          src={project.videoUrl}
          className="w-full h-full"
          title={project.title}
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
          allowFullScreen
        ></iframe>
      </div>

      <div className="max-w-7xl mx-auto px-6 mt-16">
        <Link to="/" className="inline-flex items-center text-white/40 hover:text-white transition-colors mb-12 text-sm font-bold tracking-widest">
          <ArrowLeft size={16} className="mr-2" /> BACK TO PORTFOLIO
        </Link>

        <div className="grid md:grid-cols-3 gap-16">
          <div className="md:col-span-2 space-y-12">
            <div>
              <h1 className="text-5xl md:text-7xl font-black tracking-tighter mb-8 uppercase">{project.title}</h1>
              <p className="text-xl text-white/80 leading-relaxed font-light italic border-l-4 border-blue-500 pl-8">
                "{project.description}"
              </p>
            </div>

            <section className="space-y-8">
              <h2 className="text-2xl font-bold tracking-tight border-b border-white/10 pb-4">제작 과정 (Process)</h2>
              <div className="text-white/60 leading-relaxed whitespace-pre-wrap text-lg">
                {project.process}
              </div>
            </section>

            {/* Project Still Images - Placeholders */}
            <div className="grid grid-cols-2 gap-4 pt-12">
                <img src={`https://picsum.photos/seed/${project.id}-1/800/600`} className="rounded-lg bg-white/5" alt="Process 1" />
                <img src={`https://picsum.photos/seed/${project.id}-2/800/600`} className="rounded-lg bg-white/5" alt="Process 2" />
            </div>
          </div>

          <aside className="space-y-12 pt-4">
            <div className="p-8 bg-white/5 rounded-2xl border border-white/10 space-y-8">
              <div>
                <h4 className="text-[10px] font-bold tracking-[0.3em] text-blue-400 mb-2 uppercase">Category</h4>
                <p className="font-bold">{project.category}</p>
              </div>
              <div>
                <h4 className="text-[10px] font-bold tracking-[0.3em] text-blue-400 mb-2 uppercase">Date</h4>
                <p className="font-bold">{project.date}</p>
              </div>
              {project.client && (
                <div>
                  <h4 className="text-[10px] font-bold tracking-[0.3em] text-blue-400 mb-2 uppercase">Client</h4>
                  <p className="font-bold">{project.client}</p>
                </div>
              )}
              <div className="pt-4">
                <a 
                  href={project.videoUrl} 
