export default ProjectDetail;

import React from 'react';
import { useNavigate } from 'react-router-dom';
import { Lock } from 'lucide-react';

interface AdminLoginProps {
  onLogin: () => void;
}

const AdminLogin: React.FC<AdminLoginProps> = ({ onLogin }) => {
  const [id, setId] = React.useState('');
  const [password, setPassword] = React.useState('');
  const [error, setError] = React.useState('');
  const navigate = useNavigate();

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    // In a real app, this would be an API call
    if (id === 'admin' && password === 'admin123') {
      onLogin();
      navigate('/admin/dashboard');
    } else {
      setError('아이디 또는 비밀번호가 올바르지 않습니다.');
    }
  };

  return (
    <div className="min-h-[80vh] flex items-center justify-center px-6">
      <div className="w-full max-w-md p-10 bg-[#0a0a0a] border border-white/10 rounded-3xl shadow-2xl">
        <div className="flex justify-center mb-8">
          <div className="p-4 bg-blue-500/10 rounded-full">
            <Lock className="text-blue-500" size={32} />
          </div>
        </div>
        <h2 className="text-2xl font-bold text-center mb-8 tracking-tight">관리자 로그인</h2>

        <form onSubmit={handleLogin} className="space-y-6">
          <div>
            <label className="block text-[10px] font-bold tracking-widest text-white/40 uppercase mb-2">ID</label>
            <input
              type="text"
              value={id}
              onChange={(e) => setId(e.target.value)}
              className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 focus:outline-none focus:border-blue-500 transition-colors"
              placeholder="admin"
              required
            />
          </div>
          <div>
            <label className="block text-[10px] font-bold tracking-widest text-white/40 uppercase mb-2">Password</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 focus:outline-none focus:border-blue-500 transition-colors"
              placeholder="••••••••"
              required
            />
          </div>

          {error && <p className="text-red-500 text-xs font-medium text-center">{error}</p>}

          <button
            type="submit"
            className="w-full bg-white text-black font-bold py-4 rounded-xl hover:bg-white/90 transition-all tracking-widest"
          >
            LOGIN
          </button>
        </form>
      </div>
    </div>
  );
};

export default AdminLogin;

import React from 'react';
import { Project, SiteConfig, ProjectCategory } from '../types';
import { CATEGORIES } from '../constants';
import { Plus, Trash2, Edit3, Save, X, Settings, Image as ImageIcon } from 'lucide-react';

interface AdminDashboardProps {
  projects: Project[];
  setProjects: React.Dispatch<React.SetStateAction<Project[]>>;
  config: SiteConfig;
  setConfig: React.Dispatch<React.SetStateAction<SiteConfig>>;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ projects, setProjects, config, setConfig }) => {
  const [tab, setTab] = React.useState<'projects' | 'settings'>('projects');
  const [editingProject, setEditingProject] = React.useState<Project | null>(null);
  const [isModalOpen, setIsModalOpen] = React.useState(false);

  const handleDeleteProject = (id: string) => {
    if (confirm('이 프로젝트를 삭제하시겠습니까?')) {
      setProjects(projects.filter(p => p.id !== id));
    }
  };

  const handleSaveProject = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProject) return;

    if (projects.find(p => p.id === editingProject.id)) {
      setProjects(projects.map(p => p.id === editingProject.id ? editingProject : p));
    } else {
      setProjects([...projects, editingProject]);
    }
    setIsModalOpen(false);
    setEditingProject(null);
  };

  const openNewProject = () => {
    setEditingProject({
      id: Date.now().toString(),
      title: '',
      category: ProjectCategory.MOTION,
      thumbnail: 'https://picsum.photos/seed/' + Math.random() + '/1280/720',
      videoUrl: '',
      description: '',
      process: '',
      date: new Date().toISOString().slice(0, 7).replace('-', '.'),
    });
    setIsModalOpen(true);
  };

  const openEditProject = (p: Project) => {
    setEditingProject(p);
    setIsModalOpen(true);
  };

  return (
    <div className="max-w-7xl mx-auto px-6 py-12 animate-fadeIn">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-12 gap-8">
        <div>
          <h1 className="text-4xl font-black tracking-tighter mb-2 uppercase">Dashboard</h1>
          <p className="text-white/40 font-medium">관리자 페이지에서 사이트의 모든 콘텐츠를 관리할 수 있습니다.</p>
        </div>
        <div className="flex bg-white/5 p-1 rounded-xl border border-white/10">
          <button 
            onClick={() => setTab('projects')}
            className={`px-6 py-2 rounded-lg text-sm font-bold tracking-widest transition-all ${tab === 'projects' ? 'bg-white text-black' : 'text-white/40 hover:text-white'}`}
          >
            PROJECTS
          </button>
          <button 
            onClick={() => setTab('settings')}
            className={`px-6 py-2 rounded-lg text-sm font-bold tracking-widest transition-all ${tab === 'settings' ? 'bg-white text-black' : 'text-white/40 hover:text-white'}`}
          >
            SETTINGS
          </button>
        </div>
      </div>

      {tab === 'projects' ? (
        <div className="space-y-6">
          <div className="flex justify-end">
            <button 
              onClick={openNewProject}
              className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-3 rounded-xl flex items-center gap-2 font-bold tracking-widest transition-all text-sm"
            >
              <Plus size={18} /> NEW PROJECT
            </button>
          </div>

          <div className="grid grid-cols-1 gap-4">
            {projects.map((p) => (
              <div key={p.id} className="bg-[#0a0a0a] border border-white/5 rounded-2xl p-6 flex items-center justify-between group hover:border-white/20 transition-all">
                <div className="flex items-center gap-6">
                  <div className="w-24 aspect-video rounded-lg overflow-hidden bg-white/5 border border-white/10">
                    <img src={p.thumbnail} alt="" className="w-full h-full object-cover grayscale" />
                  </div>
