import React from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Home from './pages/Home';
import ProjectDetail from './pages/ProjectDetail';
import AdminLogin from './pages/AdminLogin';
import AdminDashboard from './pages/AdminDashboard';
import { INITIAL_PROJECTS, INITIAL_CONFIG } from './constants';
import { Project, SiteConfig } from './types';

const App: React.FC = () => {
  const [projects, setProjects] = React.useState<Project[]>(() => {
    const saved = localStorage.getItem('aeju_projects');
    return saved ? JSON.parse(saved) : INITIAL_PROJECTS;
  });

  const [config, setConfig] = React.useState<SiteConfig>(() => {
    const saved = localStorage.getItem('aeju_config');
    return saved ? JSON.parse(saved) : INITIAL_CONFIG;
  });

  const [isLoggedIn, setIsLoggedIn] = React.useState<boolean>(() => {
    return sessionStorage.getItem('aeju_admin_auth') === 'true';
  });

  React.useEffect(() => {
    localStorage.setItem('aeju_projects', JSON.stringify(projects));
  }, [projects]);

  React.useEffect(() => {
    localStorage.setItem('aeju_config', JSON.stringify(config));
  }, [config]);

  const handleLogin = () => {
    setIsLoggedIn(true);
    sessionStorage.setItem('aeju_admin_auth', 'true');
  };

  return (
    <Router>
      <Layout config={config}>
        <Routes>
          <Route path="/" element={<Home projects={projects} config={config} />} />
          <Route path="/project/:id" element={<ProjectDetail projects={projects} />} />
          <Route 
            path="/admin" 
            element={isLoggedIn ? <Navigate to="/admin/dashboard" /> : <AdminLogin onLogin={handleLogin} />} 
          />
          <Route 
            path="/admin/dashboard" 
            element={
              isLoggedIn ? (
                <AdminDashboard 
                  projects={projects} 
                  setProjects={setProjects} 
                  config={config} 
                  setConfig={setConfig} 
                />
              ) : (
                <Navigate to="/admin" />
              )
            } 
          />
        </Routes>
      </Layout>
    </Router>
  );
};

export default App;

