const AdminDashboard: React.FC<AdminDashboardProps> = ({ projects, setProjects, config, setConfig }) => {
  const [tab, setTab] = React.useState<'projects' | 'settings'>('projects');
  const [editingProject, setEditingProject] = React.useState<Project | null>(null);
  const [isModalOpen, setIsModalOpen] = React.useState(false);

  const handleDeleteProject = (id: string) => {
    if (confirm('이 프로젝트를 삭제하시겠습니까?')) {
      setProjects(projects.filter(p => p.id !== id));
    }
  };

  const handleSaveProject = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProject) return;

    if (projects.find(p => p.id === editingProject.id)) {
      setProjects(projects.map(p => p.id === editingProject.id ? editingProject : p));
    } else {
      setProjects([...projects, editingProject]);
    }
    setIsModalOpen(false);
    setEditingProject(null);
  };

  const openNewProject = () => {
    setEditingProject({
      id: Date.now().toString(),
      title: '',
      category: ProjectCategory.MOTION,
      thumbnail: 'https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?auto=format&fit=crop&q=80&w=1280',
      videoUrl: '',
      description: '',
      process: '',
      date: new Date().toISOString().slice(0, 7).replace('-', '.'),
      client: ''
    });
    setIsModalOpen(true);
  };

  const openEditProject = (p: Project) => {
    setEditingProject(p);
    setIsModalOpen(true);
  };

  return (
    <div className="max-w-[1600px] mx-auto px-8 py-24 animate-fadeIn">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-end mb-24 gap-12">
        <div>
          <h1 className="text-6xl font-black tracking-tighter uppercase mb-4">Dashboard</h1>
          <p className="text-white/40 font-medium tracking-wide">CONTENT MANAGEMENT SYSTEM</p>
        </div>
        <div className="flex bg-white/5 p-1 rounded-full border border-white/5 backdrop-blur-md">
          <button 
            onClick={() => setTab('projects')}
            className={`px-8 py-3 rounded-full text-[11px] font-bold tracking-[0.2em] transition-all ${tab === 'projects' ? 'bg-[#ccff00] text-black' : 'text-white/40 hover:text-white'}`}
          >
            PROJECTS
          </button>
          <button 
            onClick={() => setTab('settings')}
            className={`px-8 py-3 rounded-full text-[11px] font-bold tracking-[0.2em] transition-all ${tab === 'settings' ? 'bg-[#ccff00] text-black' : 'text-white/40 hover:text-white'}`}
          >
            SETTINGS
          </button>
        </div>
      </div>

      {tab === 'projects' ? (
        <div className="space-y-12">
          <div className="flex justify-end">
            <button 
              onClick={openNewProject}
              className="bg-[#ccff00] text-black px-10 py-5 rounded-full flex items-center gap-3 font-bold tracking-[0.1em] transition-transform hover:scale-105 active:scale-95 text-xs uppercase"
            >
              <Plus size={18} /> Add New Entry
            </button>
          </div>

          <div className="grid grid-cols-1 gap-4">
            {projects.map((p) => (
              <div key={p.id} className="bg-white/5 border border-white/5 rounded-3xl p-8 flex flex-col md:flex-row items-center justify-between group hover:border-[#ccff00]/30 transition-all gap-8">
                <div className="flex items-center gap-10 w-full">
                  <div className="w-40 aspect-video rounded-2xl overflow-hidden bg-black border border-white/10 shrink-0">
                    <img src={p.thumbnail} alt="" className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-700" />
                  </div>
                  <div>
                    <span className="text-[10px] font-bold tracking-[0.3em] text-[#ccff00] uppercase mb-1 block">{p.category}</span>
                    <h3 className="text-2xl font-black tracking-tighter uppercase">{p.title}</h3>
                    <p className="text-sm text-white/40">{p.date}</p>
                  </div>
                </div>
                <div className="flex items-center gap-4 w-full md:w-auto justify-end">
                  <button 
                    onClick={() => openEditProject(p)}
                    className="flex-1 md:flex-none px-6 py-4 bg-white/5 hover:bg-white/10 rounded-2xl transition-colors text-white font-bold text-xs uppercase tracking-widest"
                  >
                    Edit
                  </button>
                  <button 
                    onClick={() => handleDeleteProject(p.id)}
                    className="flex-1 md:flex-none px-6 py-4 bg-white/5 hover:bg-red-500/20 rounded-2xl transition-colors text-red-500 font-bold text-xs uppercase tracking-widest"
                  >
                    Delete
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      ) : (
        <div className="max-w-3xl space-y-16">
          <div className="space-y-10">
            <div className="grid grid-cols-1 gap-12">
              <div className="space-y-4">
                <label className="block text-[10px] font-bold tracking-[0.3em] text-white/40 uppercase">Site Identity</label>
                <input 
                  type="text" 
                  value={config.siteName}
                  onChange={(e) => setConfig({...config, siteName: e.target.value})}
                  className="w-full bg-transparent border-b border-white/10 py-4 text-3xl font-black tracking-tighter focus:outline-none focus:border-[#ccff00] transition-colors uppercase"
                />
              </div>
              <div className="space-y-4">
                <label className="block text-[10px] font-bold tracking-[0.3em] text-white/40 uppercase">Introduction Statement</label>
                <textarea 
                  rows={4}
                  value={config.bio}
                  onChange={(e) => setConfig({...config, bio: e.target.value})}
                  className="w-full bg-white/5 border border-white/10 rounded-3xl p-6 focus:outline-none focus:border-[#ccff00] resize-none text-lg font-light leading-relaxed"
                />
              </div>
              <div className="space-y-4">
                <label className="block text-[10px] font-bold tracking-[0.3em] text-white/40 uppercase">Direct Email</label>
                <input 
                  type="email" 
                  value={config.contactEmail}
                  onChange={(e) => setConfig({...config, contactEmail: e.target.value})}
                  className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 focus:outline-none focus:border-[#ccff00]"
                />
              </div>
            </div>
          </div>

          <div className="pt-10">
            <button 
              onClick={() => alert('설정이 저장되었습니다.')}
              className="bg-[#ccff00] text-black px-12 py-5 rounded-full font-black tracking-widest transition-transform hover:scale-105 text-sm w-full md:w-auto uppercase"
            >
              Update Config
            </button>
          </div>
        </div>
      )}

      {/* Project Edit Modal */}
      {isModalOpen && editingProject && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/95 backdrop-blur-xl overflow-y-auto">
          <div className="bg-[#0a0a0a] border border-white/10 rounded-[40px] w-full max-w-5xl max-h-[90vh] overflow-y-auto shadow-2xl relative">
            <div className="sticky top-0 bg-[#0a0a0a]/90 backdrop-blur-md px-12 py-8 border-b border-white/5 flex items-center justify-between z-10">
              <h2 className="text-3xl font-black uppercase tracking-tighter">Edit Project</h2>
              <button onClick={() => setIsModalOpen(false)} className="text-white/40 hover:text-white p-2"><X size={32} /></button>
            </div>

            <form onSubmit={handleSaveProject} className="p-12 space-y-12">
              <div className="grid md:grid-cols-2 gap-12">
                <div className="space-y-8">
                  <div className="space-y-3">
                    <label className="text-[10px] font-bold tracking-[0.3em] text-white/40 uppercase">Project Title</label>
                    <input 
                      type="text" 
                      required
                      value={editingProject.title}
                      onChange={(e) => setEditingProject({...editingProject, title: e.target.value})}
                      className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 focus:outline-none focus:border-[#ccff00]"
                    />
                  </div>
                  <div className="space-y-3">
                    <label className="text-[10px] font-bold tracking-[0.3em] text-white/40 uppercase">Category</label>
                    <select 
                      value={editingProject.category}
                      onChange={(e) => setEditingProject({...editingProject, category: e.target.value})}
                      className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 focus:outline-none focus:border-[#ccff00] appearance-none"
                    >
                      {CATEGORIES.filter(c => c !== ProjectCategory.ALL).map(c => (
                        <option key={c} value={c}>{c}</option>
                      ))}
                    </select>
                  </div>
                  <div className="space-y-3">
                    <label className="text-[10px] font-bold tracking-[0.3em] text-white/40 uppercase">Video Embed Link</label>
                    <input 
                      type="url" 
                      required
                      value={editingProject.videoUrl}
                      onChange={(e) => setEditingProject({...editingProject, videoUrl: e.target.value})}
                      className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 focus:outline-none focus:border-[#ccff00]"
                    />
                  </div>
                </div>

                <div className="space-y-8">
                   <div className="space-y-3">
                    <label className="text-[10px] font-bold tracking-[0.3em] text-white/40 uppercase">Thumbnail URL</label>
                    <input 
                      type="url" 
                      required
                      value={editingProject.thumbnail}
                      onChange={(e) => setEditingProject({...editingProject, thumbnail: e.target.value})}
                      className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 focus:outline-none focus:border-[#ccff00]"
                    />
                    <div className="mt-4 aspect-video rounded-2xl overflow-hidden border border-white/10 bg-black">
                      <img src={editingProject.thumbnail} alt="Preview" className="w-full h-full object-cover grayscale" />
                    </div>
                  </div>
                </div>
              </div>

              <div className="space-y-8">
                <div className="space-y-3">
                  <label className="text-[10px] font-bold tracking-[0.3em] text-white/40 uppercase">One-line description</label>
                  <input 
                    type="text" 
                    required
                    value={editingProject.description}
                    onChange={(e) => setEditingProject({...editingProject, description: e.target.value})}
                    className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 focus:outline-none focus:border-[#ccff00]"
                  />
                </div>
                <div className="space-y-3">
                  <label className="text-[10px] font-bold tracking-[0.3em] text-white/40 uppercase">Creative Process</label>
                  <textarea 
                    rows={6}
                    required
                    value={editingProject.process}
                    onChange={(e) => setEditingProject({...editingProject, process: e.target.value})}
                    className="w-full bg-white/5 border border-white/10 rounded-3xl p-6 focus:outline-none focus:border-[#ccff00] resize-none font-light"
                  />
                </div>
              </div>

              <div className="pt-12 border-t border-white/5 flex justify-end gap-6">
                <button 
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="px-10 py-5 rounded-full font-bold text-white/40 hover:text-white transition-colors text-xs uppercase tracking-widest"
                >
                  Discard
                </button>
                <button 
                  type="submit"
                  className="bg-[#ccff00] text-black px-14 py-5 rounded-full font-black tracking-widest transition-transform hover:scale-105 text-sm uppercase flex items-center gap-2 shadow-2xl shadow-[#ccff00]/10"
                >
                  <Save size={18} /> Push to Live
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { Project } from '../types';
import { ArrowLeft, ExternalLink } from 'lucide-react';

interface ProjectDetailProps {
  projects: Project[];
}

const ProjectDetail: React.FC<ProjectDetailProps> = ({ projects }) => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const project = projects.find(p => p.id === id);

  React.useEffect(() => {
    window.scrollTo(0, 0);
  }, [id]);

  if (!project) {
    return (
      <div className="h-screen flex items-center justify-center">
        <p>프로젝트를 찾을 수 없습니다.</p>
        <button onClick={() => navigate('/')} className="ml-4 underline">홈으로</button>
      </div>
    );
  }

  return (
    <div className="pb-48 animate-fadeIn">
      {/* Cinematic Video Player */}
      <div className="w-full aspect-video bg-black relative group border-b border-white/5">
        <iframe
          src={project.videoUrl}
          className="w-full h-full"
          title={project.title}
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
          allowFullScreen
        ></iframe>
      </div>

      <div className="max-w-[1600px] mx-auto px-8 mt-24">
        <Link to="/" className="inline-flex items-center text-white/30 hover:text-[#ccff00] transition-colors mb-24 text-[10px] font-bold tracking-[0.4em] uppercase">
          <ArrowLeft size={14} className="mr-3" /> BACK TO INDEX
        </Link>

        <div className="grid lg:grid-cols-12 gap-24">
          <div className="lg:col-span-8 space-y-24">
            <div>
              <h1 className="text-7xl md:text-[8vw] font-black tracking-tighter mb-12 uppercase leading-[0.85]">{project.title}</h1>
              <p className="text-2xl md:text-4xl text-white/60 leading-tight font-light border-l border-[#ccff00] pl-12 max-w-3xl">
                {project.description}
              </p>
            </div>

            <section className="space-y-12">
              <h2 className="text-[11px] font-bold tracking-[0.5em] text-[#ccff00] uppercase">The Creative Process</h2>
              <div className="text-white/50 leading-relaxed whitespace-pre-wrap text-xl font-light max-w-3xl">
                {project.process}
              </div>
            </section>

            {/* Project Stills */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-12">
                <div className="overflow-hidden border border-white/5 aspect-video">
                  <img src={`https://images.unsplash.com/photo-1614850523296-d8c1af93d400?auto=format&fit=crop&q=80&w=800`} className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-1000" alt="Detail 1" />
                </div>
                <div className="overflow-hidden border border-white/5 aspect-video">
                  <img src={`https://images.unsplash.com/photo-1633167606207-d840b5070fc2?auto=format&fit=crop&q=80&w=800`} className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-1000" alt="Detail 2" />
                </div>
            </div>
          </div>

          <aside className="lg:col-span-4 lg:sticky lg:top-32 h-fit">
            <div className="p-12 bg-white/5 border border-white/5 rounded-[40px] space-y-12 backdrop-blur-md">
              <div className="grid grid-cols-1 gap-12">
                <div>
                  <h4 className="text-[9px] font-bold tracking-[0.4em] text-white/30 mb-3 uppercase">Category</h4>
                  <p className="text-xl font-bold uppercase tracking-tighter">{project.category}</p>
                </div>
                <div>
                  <h4 className="text-[9px] font-bold tracking-[0.4em] text-white/30 mb-3 uppercase">Timeline</h4>
                  <p className="text-xl font-bold tracking-tighter">{project.date}</p>
                </div>
                {project.client && (
                  <div>
                    <h4 className="text-[9px] font-bold tracking-[0.4em] text-white/30 mb-3 uppercase">Client</h4>
                    <p className="text-xl font-bold uppercase tracking-tighter">{project.client}</p>
                  </div>
                )}
              </div>
              <div className="pt-6">
                <a 
                  href={project.videoUrl} 
                  target="_blank" 
                  rel="noopener noreferrer"
                  className="w-full py-6 flex items-center justify-center bg-[#ccff00] text-black hover:scale-[1.02] active:scale-[0.98] transition-all rounded-full font-black tracking-widest text-xs uppercase"
                >
                  Watch Source <ExternalLink size={14} className="ml-3" />
                </a>
              </div>
            </div>
          </aside>
        </div>
      </div>
    </div>
  );
};

export default ProjectDetail;

import React from 'react';
import { useNavigate } from 'react-router-dom';
import { Lock } from 'lucide-react';

interface AdminLoginProps {
  onLogin: () => void;
}

const AdminLogin: React.FC<AdminLoginProps> = ({ onLogin }) => {
  const [id, setId] = React.useState('');
  const [password, setPassword] = React.useState('');
  const [error, setError] = React.useState('');
  const navigate = useNavigate();

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (id === 'admin' && password === 'admin123') {
      onLogin();
      navigate('/admin/dashboard');
    } else {
      setError('접근 권한이 없습니다.');
    }
  };

  return (
    <div className="min-h-[80vh] flex items-center justify-center px-8">
      <div className="w-full max-w-lg p-16 bg-white/5 border border-white/5 rounded-[48px] backdrop-blur-2xl shadow-2xl relative overflow-hidden">
        {/* Glow effect */}
        <div className="absolute top-[-50%] left-[-50%] w-full h-full bg-[#ccff00]/10 blur-[120px] rounded-full pointer-events-none"></div>

        <div className="relative z-10">
          <div className="flex justify-center mb-12">
            <div className="p-6 bg-[#ccff00] rounded-full">
              <Lock className="text-black" size={32} />
            </div>
          </div>
          <h2 className="text-4xl font-black text-center mb-12 tracking-tighter uppercase">Authorized Only</h2>

          <form onSubmit={handleLogin} className="space-y-8">
            <div className="space-y-3">
              <label className="block text-[10px] font-bold tracking-[0.4em] text-white/30 uppercase ml-4">Identifier</label>
              <input
                type="text"
                value={id}
                onChange={(e) => setId(e.target.value)}
                className="w-full bg-white/5 border border-white/10 rounded-full px-8 py-5 focus:outline-none focus:border-[#ccff00] transition-colors"
                placeholder="admin"
                required
              />
            </div>
            <div className="space-y-3">
              <label className="block text-[10px] font-bold tracking-[0.4em] text-white/30 uppercase ml-4">Credential</label>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full bg-white/5 border border-white/10 rounded-full px-8 py-5 focus:outline-none focus:border-[#ccff00] transition-colors"
                placeholder="••••••••"
                required
              />
            </div>

            {error && <p className="text-red-500 text-[11px] font-bold tracking-widest text-center uppercase">{error}</p>}

            <button
              type="submit"
              className="w-full bg-[#ccff00] text-black font-black py-6 rounded-full hover:scale-[1.02] active:scale-[0.98] transition-all tracking-[0.2em] text-xs uppercase"
            >
              Enter Dashboard
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

