import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Menu, X } from 'lucide-react';
import { SiteConfig } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  config: SiteConfig;
}

const Layout: React.FC<LayoutProps> = ({ children, config }) => {
  const [isMenuOpen, setIsMenuOpen] = React.useState(false);
  const location = useLocation();

  const navLinks = [
    { name: 'INDEX', path: '/' },
    { name: 'ABOUT', path: '/#about' },
    { name: 'DASHBOARD', path: '/admin' },
  ];

  return (
    <div className="min-h-screen flex flex-col bg-black selection:bg-white selection:text-black">
      {/* Navigation */}
      <nav className="fixed w-full z-40 px-8 md:px-12 py-10 flex items-center justify-between mix-blend-difference pointer-events-none">
        <Link to="/" className="text-xl font-black tracking-tighter uppercase pointer-events-auto">
          {config.siteName}
        </Link>

        {/* Desktop Navigation */}
        <div className="hidden md:flex items-center space-x-12 pointer-events-auto">
          {navLinks.map((link) => (
            <Link
              key={link.path}
              to={link.path}
              className="text-[10px] font-medium tracking-[0.4em] text-white hover:opacity-50 transition-opacity uppercase"
            >
              {link.name}
            </Link>
          ))}
        </div>

        {/* Mobile Menu Button */}
        <button 
          className="md:hidden text-white pointer-events-auto p-2"
          onClick={() => setIsMenuOpen(!isMenuOpen)}
        >
          {isMenuOpen ? <X size={20} /> : <Menu size={20} />}
        </button>
      </nav>

      {/* Mobile Nav Overlay */}
      {isMenuOpen && (
