import React from 'react';
import { Project, SiteConfig } from '../types';
import { CATEGORIES } from '../constants';
import { Plus, Trash2, Edit3, Save, X } from 'lucide-react';

interface AdminDashboardProps {
  projects: Project[];
  setProjects: React.Dispatch<React.SetStateAction<Project[]>>;
  config: SiteConfig;
  setConfig: React.Dispatch<React.SetStateAction<SiteConfig>>;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ projects, setProjects, config, setConfig }) => {
  const [tab, setTab] = React.useState<'projects' | 'settings'>('projects');
  const [editingProject, setEditingProject] = React.useState<Project | null>(null);
  const [isModalOpen, setIsModalOpen] = React.useState(false);

  const handleDeleteProject = (id: string) => {
    if (confirm('Permanently delete this project?')) {
      setProjects(projects.filter(p => p.id !== id));
    }
  };

  const handleSaveProject = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProject) return;

    if (projects.find(p => p.id === editingProject.id)) {
      setProjects(projects.map(p => p.id === editingProject.id ? editingProject : p));
    } else {
      setProjects([...projects, editingProject]);
    }
    setIsModalOpen(false);
    setEditingProject(null);
  };

  const openNewProject = () => {
    setEditingProject({
      id: Date.now().toString(),
      title: '',
      category: 'Motion Design',
      thumbnail: '',
      videoUrl: '',
      description: '',
      process: '',
      date: new Date().toISOString().slice(0, 7).replace('-', '.'),
      client: ''
    });
    setIsModalOpen(true);
  };

  const openEditProject = (p: Project) => {
    setEditingProject(p);
    setIsModalOpen(true);
  };

  return (
    <div className="max-w-[1400px] mx-auto px-8 py-32 animate-fadeIn">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-end mb-24 gap-12">
        <div className="space-y-4">
          <h1 className="text-6xl md:text-8xl font-serif italic tracking-tighter uppercase">Studio Panel</h1>
          <p className="text-[10px] font-bold tracking-[0.4em] text-white/30 uppercase">Content Control System</p>
        </div>
        <div className="flex bg-white/5 border border-white/10 p-1">
          <button 
            onClick={() => setTab('projects')}
            className={`px-8 py-3 text-[10px] font-bold tracking-[0.2em] transition-all uppercase ${tab === 'projects' ? 'bg-white text-black' : 'text-white/40 hover:text-white'}`}
          >
            Index
          </button>
          <button 
            onClick={() => setTab('settings')}
            className={`px-8 py-3 text-[10px] font-bold tracking-[0.2em] transition-all uppercase ${tab === 'settings' ? 'bg-white text-black' : 'text-white/40 hover:text-white'}`}
          >
            Identity
          </button>
        </div>
      </div>

      {tab === 'projects' ? (
        <div className="space-y-16">
          <div className="flex justify-end">
            <button 
              onClick={openNewProject}
              className="bg-white text-black px-8 py-4 flex items-center gap-3 font-bold tracking-widest text-[10px] uppercase transition-transform hover:scale-105"
            >
              <Plus size={16} /> New Entry
            </button>
          </div>

          <div className="divide-y divide-white/5">
            {projects.map((p) => (
              <div key={p.id} className="py-10 flex flex-col md:flex-row items-center justify-between group gap-8">
                <div className="flex items-center gap-12 w-full">
                  <div className="w-48 aspect-[4/3] bg-[#111] shrink-0 border border-white/5">
                    <img src={p.thumbnail} alt="" className="w-full h-full object-cover grayscale opacity-50 group-hover:opacity-100 transition-opacity" />
                  </div>
                  <div>
                    <span className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase mb-2 block">{p.category}</span>
                    <h3 className="text-3xl font-serif italic uppercase tracking-tighter group-hover:text-white transition-colors">{p.title}</h3>
                  </div>
                </div>
                <div className="flex items-center gap-8 shrink-0">
                  <button onClick={() => openEditProject(p)} className="text-[10px] font-bold tracking-widest text-white/30 hover:text-white uppercase flex items-center gap-2">
                    <Edit3 size={14} /> EDIT
                  </button>
                  <button onClick={() => handleDeleteProject(p.id)} className="text-[10px] font-bold tracking-widest text-red-900 hover:text-red-500 uppercase flex items-center gap-2">
                    <Trash2 size={14} /> REMOVE
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      ) : (
        <div className="max-w-2xl space-y-24">
          <div className="space-y-12">
            <div className="space-y-4">
              <label className="text-[10px] font-bold tracking-[0.4em] text-white/30 uppercase">Site Title</label>
              <input 
                type="text" 
                value={config.siteName}
                onChange={(e) => setConfig({...config, siteName: e.target.value})}
                className="w-full bg-transparent border-b border-white/10 py-4 text-4xl font-serif italic tracking-tighter uppercase focus:outline-none focus:border-white"
              />
            </div>
            <div className="space-y-4">
              <label className="text-[10px] font-bold tracking-[0.4em] text-white/30 uppercase">Bio / Statement</label>
              <textarea 
                rows={4}
                value={config.bio}
                onChange={(e) => setConfig({...config, bio: e.target.value})}
                className="w-full bg-transparent border border-white/10 p-6 text-xl font-light focus:outline-none focus:border-white resize-none"
