            Commit Changes
          </button>
        </div>
      )}

      {/* Modal */}
      {isModalOpen && editingProject && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/95 backdrop-blur-sm overflow-y-auto">
          <div className="bg-black border border-white/10 w-full max-w-4xl max-h-[90vh] overflow-y-auto relative p-12">
            <button onClick={() => setIsModalOpen(false)} className="absolute top-12 right-12 text-white/30 hover:text-white transition-colors"><X size={32} /></button>
            <h2 className="text-5xl font-serif italic mb-16 uppercase tracking-tighter">Project Editor</h2>

            <form onSubmit={handleSaveProject} className="space-y-12">
              <div className="grid md:grid-cols-2 gap-12">
                <div className="space-y-8">
                  <div className="space-y-2">
                    <label className="text-[10px] font-bold tracking-[0.3em] text-white/30 uppercase">Title</label>
                    <input type="text" required value={editingProject.title} onChange={(e) => setEditingProject({...editingProject, title: e.target.value})} className="w-full bg-transparent border-b border-white/10 py-3 text-lg focus:outline-none focus:border-white"/>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-bold tracking-[0.3em] text-white/30 uppercase">Category</label>
                    <input type="text" required value={editingProject.category} onChange={(e) => setEditingProject({...editingProject, category: e.target.value})} className="w-full bg-transparent border-b border-white/10 py-3 text-lg focus:outline-none focus:border-white" placeholder="e.g. Motion Design"/>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-bold tracking-[0.3em] text-white/30 uppercase">Video URL</label>
                    <input type="url" required value={editingProject.videoUrl} onChange={(e) => setEditingProject({...editingProject, videoUrl: e.target.value})} className="w-full bg-transparent border-b border-white/10 py-3 text-lg focus:outline-none focus:border-white"/>
