import React from 'react';
import { Project, SiteConfig } from '../types';
import { CATEGORIES } from '../constants';
import { Plus, Trash2, Edit3, Save, X } from 'lucide-react';

interface AdminDashboardProps {
  projects: Project[];
  setProjects: React.Dispatch<React.SetStateAction<Project[]>>;
  config: SiteConfig;
  setConfig: React.Dispatch<React.SetStateAction<SiteConfig>>;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ projects, setProjects, config, setConfig }) => {
  const [tab, setTab] = React.useState<'projects' | 'settings'>('projects');
  const [editingProject, setEditingProject] = React.useState<Project | null>(null);
  const [isModalOpen, setIsModalOpen] = React.useState(false);

  const handleDeleteProject = (id: string) => {
    if (confirm('이 데이터를 삭제하시겠습니까?')) {
      setProjects(projects.filter(p => p.id !== id));
    }
  };

  const handleSaveProject = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProject) return;

    if (projects.find(p => p.id === editingProject.id)) {
      setProjects(projects.map(p => p.id === editingProject.id ? editingProject : p));
    } else {
      setProjects([...projects, editingProject]);
    }
    setIsModalOpen(false);
    setEditingProject(null);
  };

  const openNewProject = () => {
    setEditingProject({
      id: Date.now().toString(),
      title: '',
      category: '모션 디자인',
      thumbnail: '',
      videoUrl: '',
      description: '',
      process: '',
      date: new Date().toISOString().slice(0, 7).replace('-', '.'),
      client: ''
    });
    setIsModalOpen(true);
  };

  return (
    <div className="max-w-7xl mx-auto px-6 py-20 animate-fadeIn">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end mb-20 gap-8">
        <div>
          <h1 className="text-5xl font-display font-black uppercase tracking-tighter">System</h1>
          <p className="text-white/20 text-xs tracking-widest mt-2 uppercase">Content Management Terminal</p>
        </div>
        <div className="flex space-x-4 border border-white/5 p-1">
          <button 
            onClick={() => setTab('projects')}
            className={`px-6 py-2 text-[10px] font-bold tracking-widest uppercase transition-all ${tab === 'projects' ? 'bg-white text-black' : 'text-white/40 hover:text-white'}`}
          >
            Project Index
          </button>
          <button 
            onClick={() => setTab('settings')}
            className={`px-6 py-2 text-[10px] font-bold tracking-widest uppercase transition-all ${tab === 'settings' ? 'bg-white text-black' : 'text-white/40 hover:text-white'}`}
          >
            Identity
          </button>
        </div>
      </div>

      {tab === 'projects' ? (
        <div className="space-y-12">
          <div className="flex justify-end">
            <button 
              onClick={openNewProject}
              className="bg-white text-black px-6 py-3 flex items-center gap-2 font-bold tracking-widest text-[10px] uppercase transition-transform hover:scale-105"
            >
              <Plus size={14} /> New Entry
            </button>
          </div>

          <div className="grid grid-cols-1 gap-px bg-white/5 border border-white/5">
            {projects.map((p) => (
              <div key={p.id} className="bg-[#121212] p-8 flex flex-col md:flex-row items-center justify-between gap-8 group">
                <div className="flex items-center gap-10 w-full">
                  <div className="w-32 aspect-video bg-white/5 shrink-0 border border-white/5">
                    <img src={p.thumbnail} alt="" className="w-full h-full object-cover grayscale opacity-40 group-hover:opacity-100 transition-opacity" />
                  </div>
                  <div className="space-y-1">
                    <span className="text-[9px] text-white/20 uppercase tracking-[0.2em]">{p.category}</span>
                    <h3 className="text-xl font-bold tracking-tight uppercase">{p.title}</h3>
                  </div>
                </div>
                <div className="flex items-center space-x-6 shrink-0">
                  <button onClick={() => setEditingProject(p) || setIsModalOpen(true)} className="text-[10px] font-bold tracking-widest text-white/30 hover:text-white uppercase">Edit</button>
                  <button onClick={() => handleDeleteProject(p.id)} className="text-[10px] font-bold tracking-widest text-red-900 hover:text-red-500 uppercase">Remove</button>
                </div>
              </div>
            ))}
          </div>
        </div>
      ) : (
        <div className="max-w-xl space-y-16">
          <div className="space-y-10">
            <div className="space-y-4">
              <label className="text-[10px] text-white/20 uppercase tracking-widest">Global Title</label>
              <input 
                type="text" 
                value={config.siteName}
                onChange={(e) => setConfig({...config, siteName: e.target.value})}
                className="w-full bg-transparent border-b border-white/5 py-4 text-2xl font-display font-black uppercase tracking-tight focus:outline-none focus:border-white transition-colors"
              />
            </div>
            <div className="space-y-4">
              <label className="text-[10px] text-white/20 uppercase tracking-widest">Bio / Intro</label>
              <textarea 
                rows={4}
                value={config.bio}
                onChange={(e) => setConfig({...config, bio: e.target.value})}
                className="w-full bg-transparent border border-white/5 p-6 text-lg font-medium focus:outline-none focus:border-white transition-colors resize-none"
              />
            </div>
          </div>
          <button onClick={() => alert('Updated.')} className="bg-white text-black px-10 py-4 font-bold tracking-widest text-[10px] uppercase">Commit Changes</button>
        </div>
      )}

      {/* Modal - Modern Slim Design */}
      {isModalOpen && editingProject && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[#121212]/95 backdrop-blur-sm overflow-y-auto">
          <div className="bg-[#121212] border border-white/10 w-full max-w-4xl p-10 relative">
            <button onClick={() => setIsModalOpen(false)} className="absolute top-8 right-8 text-white/20 hover:text-white transition-colors"><X size={24} /></button>
            <h2 className="text-3xl font-display font-black uppercase tracking-tighter mb-12">Project Editor</h2>

            <form onSubmit={handleSaveProject} className="space-y-10">
              <div className="grid md:grid-cols-2 gap-10">
                <div className="space-y-6">
                  <div className="space-y-2">
                    <label className="text-[10px] text-white/20 uppercase tracking-widest">Project Title</label>
                    <input type="text" required value={editingProject.title} onChange={(e) => setEditingProject({...editingProject, title: e.target.value})} className="w-full bg-transparent border-b border-white/5 py-2 text-lg focus:outline-none focus:border-white"/>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] text-white/20 uppercase tracking-widest">Category</label>
                    <input type="text" required value={editingProject.category} onChange={(e) => setEditingProject({...editingProject, category: e.target.value})} className="w-full bg-transparent border-b border-white/5 py-2 text-lg focus:outline-none focus:border-white"/>
                  </div>
                </div>
                <div className="space-y-6">
                  <div className="space-y-2">
                    <label className="text-[10px] text-white/20 uppercase tracking-widest">Video URL</label>
                    <input type="url" required value={editingProject.videoUrl} onChange={(e) => setEditingProject({...editingProject, videoUrl: e.target.value})} className="w-full bg-transparent border-b border-white/5 py-2 text-lg focus:outline-none focus:border-white"/>
                  </div>
                   <div className="space-y-2">
                    <label className="text-[10px] text-white/20 uppercase tracking-widest">Thumbnail URL</label>
                    <input type="url" required value={editingProject.thumbnail} onChange={(e) => setEditingProject({...editingProject, thumbnail: e.target.value})} className="w-full bg-transparent border-b border-white/5 py-2 text-lg focus:outline-none focus:border-white"/>
                  </div>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] text-white/20 uppercase tracking-widest">Description</label>
                <textarea rows={2} required value={editingProject.description} onChange={(e) => setEditingProject({...editingProject, description: e.target.value})} className="w-full bg-transparent border border-white/5 p-4 focus:outline-none focus:border-white resize-none"/>
              </div>

              <div className="flex justify-end pt-8">
                <button type="submit" className="bg-white text-black px-12 py-4 font-bold tracking-widest text-[10px] uppercase">Deploy Project</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

