import React from 'react';
import { useNavigate } from 'react-router-dom';

interface AdminLoginProps {
  onLogin: () => void;
}

const AdminLogin: React.FC<AdminLoginProps> = ({ onLogin }) => {
  const [id, setId] = React.useState('');
  const [password, setPassword] = React.useState('');
  const [error, setError] = React.useState('');
  const navigate = useNavigate();

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (id === 'admin' && password === 'admin123') {
      onLogin();
      navigate('/admin/dashboard');
    } else {
      setError('인증 정보가 유효하지 않습니다.');
    }
  };

  return (
    <div className="min-h-[80vh] flex items-center justify-center px-6">
      <div className="w-full max-w-xs space-y-16">
        <div className="text-center space-y-4">
          <h1 className="text-4xl font-display font-black uppercase tracking-tighter">Gateway</h1>
          <p className="text-[10px] font-bold tracking-[0.4em] text-white/20 uppercase">Admin Authentication</p>
        </div>

        <form onSubmit={handleLogin} className="space-y-8">
          <div className="space-y-6">
            <input
              type="text"
              value={id}
              onChange={(e) => setId(e.target.value)}
              className="w-full bg-transparent border-b border-white/10 py-3 text-sm focus:outline-none focus:border-white transition-colors"
              placeholder="IDENTITY"
              required
            />
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full bg-transparent border-b border-white/10 py-3 text-sm focus:outline-none focus:border-white transition-colors"
              placeholder="CREDENTIAL"
              required
            />
          </div>

          {error && <p className="text-red-900 text-[10px] font-bold tracking-widest text-center uppercase">{error}</p>}

          <button
            type="submit"
            className="w-full bg-white text-black font-bold py-4 hover:bg-white/90 transition-all tracking-widest text-[10px] uppercase"
          >
            Enter System
          </button>
        </form>
      </div>
    </div>
  );
};

