import React from 'react';
import { Project, SiteConfig } from '../types';
import { CATEGORIES } from '../constants';
import { Plus, Trash2, Edit3, Save, X } from 'lucide-react';

interface AdminDashboardProps {
  projects: Project[];
  setProjects: React.Dispatch<React.SetStateAction<Project[]>>;
  config: SiteConfig;
  setConfig: React.Dispatch<React.SetStateAction<SiteConfig>>;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ projects, setProjects, config, setConfig }) => {
  const [tab, setTab] = React.useState<'projects' | 'settings'>('projects');
  const [editingProject, setEditingProject] = React.useState<Project | null>(null);
  const [isModalOpen, setIsModalOpen] = React.useState(false);

  const handleDeleteProject = (id: string) => {
    if (confirm('삭제하시겠습니까?')) {
      setProjects(projects.filter(p => p.id !== id));
    }
  };

  const handleSaveProject = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProject) return;

    if (projects.find(p => p.id === editingProject.id)) {
      setProjects(projects.map(p => p.id === editingProject.id ? editingProject : p));
    } else {
      setProjects([...projects, editingProject]);
    }
    setIsModalOpen(false);
    setEditingProject(null);
  };

  const openNewProject = () => {
    setEditingProject({
      id: Date.now().toString(),
      title: '',
      category: '모션 디자인',
      thumbnail: '',
      videoUrl: '',
      description: '',
      process: '',
      date: new Date().toISOString().slice(0, 7).replace('-', '.'),
      client: ''
    });
    setIsModalOpen(true);
  };

  return (
    <div className="max-w-[1400px] mx-auto px-6 py-20 animate-reveal">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end mb-16 gap-8">
        <div>
          <h1 className="text-3xl font-display font-black uppercase tracking-tighter">Terminal</h1>
          <p className="text-white/20 text-[10px] tracking-widest mt-2 uppercase font-bold">Management System</p>
        </div>
        <div className="flex space-x-2 border border-white/5 p-1 bg-white/[0.02]">
          <button 
            onClick={() => setTab('projects')}
            className={`px-6 py-2 text-[10px] font-bold tracking-widest uppercase transition-all ${tab === 'projects' ? 'bg-[#0066FF] text-white' : 'text-white/30 hover:text-white'}`}
          >
            INDEX
          </button>
          <button 
            onClick={() => setTab('settings')}
            className={`px-6 py-2 text-[10px] font-bold tracking-widest uppercase transition-all ${tab === 'settings' ? 'bg-[#0066FF] text-white' : 'text-white/30 hover:text-white'}`}
          >
            IDENTITY
          </button>
        </div>
      </div>

      {tab === 'projects' ? (
        <div className="space-y-10">
          <div className="flex justify-end">
            <button 
              onClick={openNewProject}
              className="bg-[#0066FF] text-white px-6 py-3 flex items-center gap-2 font-bold tracking-widest text-[10px] uppercase transition-transform hover:scale-105"
            >
              <Plus size={14} /> NEW ENTRY
            </button>
          </div>

          <div className="grid grid-cols-1 gap-px bg-white/5 border border-white/5">
            {projects.map((p) => (
              <div key={p.id} className="bg-[#121212] p-8 flex flex-col md:flex-row items-center justify-between gap-8 group">
                <div className="flex items-center gap-8 w-full">
                  <div className="w-24 aspect-video bg-white/5 shrink-0 border border-white/5 overflow-hidden">
                    <img src={p.thumbnail} alt="" className="w-full h-full object-cover grayscale opacity-20 group-hover:opacity-100 transition-opacity" />
                  </div>
                  <div className="space-y-1">
                    <span className="text-[9px] text-[#0066FF] uppercase tracking-[0.2em] font-bold">{p.category}</span>
                    <h3 className="text-lg font-bold tracking-tight uppercase">{p.title}</h3>
                  </div>
                </div>
                <div className="flex items-center space-x-6 shrink-0">
                  <button onClick={() => setEditingProject(p) || setIsModalOpen(true)} className="text-[10px] font-bold tracking-widest text-white/30 hover:text-white uppercase">Edit</button>
                  <button onClick={() => handleDeleteProject(p.id)} className="text-[10px] font-bold tracking-widest text-red-900 hover:text-red-500 uppercase">Remove</button>
                </div>
              </div>
            ))}
          </div>
        </div>
      ) : (
        <div className="max-w-xl space-y-12">
          <div className="space-y-8">
            <div className="space-y-3">
              <label className="text-[10px] text-white/20 uppercase tracking-widest font-bold">Global Title</label>
              <input 
                type="text" 
                value={config.siteName}
                onChange={(e) => setConfig({...config, siteName: e.target.value})}
                className="w-full bg-transparent border-b border-white/5 py-4 text-xl font-display font-black uppercase tracking-tight focus:outline-none focus:border-[#0066FF] transition-colors"
              />
            </div>
            <div className="space-y-3">
              <label className="text-[10px] text-white/20 uppercase tracking-widest font-bold">Bio / Statement</label>
              <textarea 
                rows={4}
                value={config.bio}
                onChange={(e) => setConfig({...config, bio: e.target.value})}
                className="w-full bg-transparent border border-white/5 p-6 text-base font-medium focus:outline-none focus:border-[#0066FF] transition-colors resize-none"
              />
            </div>
          </div>
          <button onClick={() => alert('Identity Confirmed.')} className="bg-[#0066FF] text-white px-10 py-4 font-bold tracking-widest text-[10px] uppercase">Commit Changes</button>
        </div>
      )}

      {/* Modal Editor */}
      {isModalOpen && editingProject && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/95 backdrop-blur-sm overflow-y-auto">
          <div className="bg-[#121212] border border-white/10 w-full max-w-4xl p-10 relative">
            <button onClick={() => setIsModalOpen(false)} className="absolute top-8 right-8 text-white/20 hover:text-white transition-colors"><X size={20} /></button>
            <h2 className="text-2xl font-display font-black uppercase tracking-tighter mb-10">Entry Editor</h2>

            <form onSubmit={handleSaveProject} className="space-y-8 text-sm">
              <div className="grid md:grid-cols-2 gap-8">
                <div className="space-y-4">
                  <label className="text-[9px] text-white/20 uppercase tracking-widest font-bold">Title</label>
                  <input type="text" required value={editingProject.title} onChange={(e) => setEditingProject({...editingProject, title: e.target.value})} className="w-full bg-transparent border-b border-white/5 py-2 focus:outline-none focus:border-[#0066FF]"/>
                </div>
                <div className="space-y-4">
                  <label className="text-[9px] text-white/20 uppercase tracking-widest font-bold">Category</label>
                  <input type="text" required value={editingProject.category} onChange={(e) => setEditingProject({...editingProject, category: e.target.value})} className="w-full bg-transparent border-b border-white/5 py-2 focus:outline-none focus:border-[#0066FF]"/>
                </div>
              </div>

              <div className="space-y-4">
                <label className="text-[9px] text-white/20 uppercase tracking-widest font-bold">Description</label>
                <textarea rows={2} required value={editingProject.description} onChange={(e) => setEditingProject({...editingProject, description: e.target.value})} className="w-full bg-transparent border border-white/5 p-4 focus:outline-none focus:border-[#0066FF] resize-none"/>
              </div>

              <div className="flex justify-end pt-4">
                <button type="submit" className="bg-[#0066FF] text-white px-10 py-4 font-bold tracking-widest text-[10px] uppercase">Save Entity</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

